import{_ as i,o as t,c as e,a4 as l}from"./chunks/framework.vNSRaLQv.js";const _=JSON.parse('{"title":"总结：ZTE B860AV1.1-T2 改造成果","description":"","frontmatter":{"title":"总结：ZTE B860AV1.1-T2 改造成果","date":"2026-07-25T00:00:00.000Z"},"headers":[],"relativePath":"posts/09_summary.md","filePath":"posts/09_summary.md"}'),o={name:"posts/09_summary.md"};function r(s,a,n,h,d,c){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="总结-zte-b860av1-1-t2-改造成果" tabindex="-1">总结：ZTE B860AV1.1-T2 改造成果 <a class="header-anchor" href="#总结-zte-b860av1-1-t2-改造成果" aria-label="Permalink to &quot;总结：ZTE B860AV1.1-T2 改造成果&quot;">​</a></h1><h2 id="已完成" tabindex="-1">已完成 <a class="header-anchor" href="#已完成" aria-label="Permalink to &quot;已完成&quot;">​</a></h2><h3 id="_1-wifi-连接" tabindex="-1">1. WiFi 连接 <a class="header-anchor" href="#_1-wifi-连接" aria-label="Permalink to &quot;1. WiFi 连接&quot;">​</a></h3><ul><li>加载 8189fs 驱动</li><li>wpa_supplicant 连接 WPA2</li><li>dhcpcd 获取 IP</li></ul><h3 id="_2-ssh-远程管理" tabindex="-1">2. SSH 远程管理 <a class="header-anchor" href="#_2-ssh-远程管理" aria-label="Permalink to &quot;2. SSH 远程管理&quot;">​</a></h3><ul><li>dropbear v0.52 监听端口 22</li><li>root 密码已配置</li></ul><h3 id="_3-内存优化-运行时" tabindex="-1">3. 内存优化（运行时） <a class="header-anchor" href="#_3-内存优化-运行时" aria-label="Permalink to &quot;3. 内存优化（运行时）&quot;">​</a></h3><ul><li>原始：733 MB 已用，280 MB 空闲</li><li>Kill Android 后：300 MB 已用，714 MB 空闲</li></ul><h3 id="_4-cma-内存回收-永久" tabindex="-1">4. CMA 内存回收（永久） <a class="header-anchor" href="#_4-cma-内存回收-永久" aria-label="Permalink to &quot;4. CMA 内存回收（永久）&quot;">​</a></h3><ul><li>DTB 修改：multimedia_region 272 MB → 16 MB</li><li>效果：CmaTotal 从 336 MB 降到 36 MB</li><li>总空闲内存：714 MB（运行时 kill + CMA 优化）</li></ul><h3 id="_5-开机自启-install-recovery-sh" tabindex="-1">5. 开机自启（install-recovery.sh） <a class="header-anchor" href="#_5-开机自启-install-recovery-sh" aria-label="Permalink to &quot;5. 开机自启（install-recovery.sh）&quot;">​</a></h3><p>通过 <code>/system/etc/install-recovery.sh</code> 钩子，开机自动：</p><ul><li>加载 WiFi 驱动</li><li>连接 WiFi</li><li>启动 SSH</li></ul><h2 id="未完成" tabindex="-1">未完成 <a class="header-anchor" href="#未完成" aria-label="Permalink to &quot;未完成&quot;">​</a></h2><h3 id="_1-init-rc-改造" tabindex="-1">1. Init.rc 改造 <a class="header-anchor" href="#_1-init-rc-改造" aria-label="Permalink to &quot;1. Init.rc 改造&quot;">​</a></h3><p>分析了 init.rc 结构，制定了改造方案（删除 Android 服务，添加 linux_init 服务），但未实际刷入验证。原因：改 ramdisk 大小会导致 DTB 偏移变化，需要精确控制。</p><h3 id="_2-cma-0-测试" tabindex="-1">2. CMA=0 测试 <a class="header-anchor" href="#_2-cma-0-测试" aria-label="Permalink to &quot;2. CMA=0 测试&quot;">​</a></h3><p>CMA 设为 0 导致内核 panic。最小可用值约 16 MB。</p><h3 id="_3-tftp-网络刷机" tabindex="-1">3. TFTP 网络刷机 <a class="header-anchor" href="#_3-tftp-网络刷机" aria-label="Permalink to &quot;3. TFTP 网络刷机&quot;">​</a></h3><p>u-boot 的 tftpboot 命令传输超时，未解决。使用 recovery + dd 方案替代。</p><h2 id="关键教训" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训" aria-label="Permalink to &quot;关键教训&quot;">​</a></h2><ol><li><strong>Boot.img 改动必须保持文件大小一致</strong> — DTB 偏移是固定的</li><li><strong>DTB 没有 CRC32</strong> — offset 4-7 是 totalsize</li><li><strong>CMA 不能为 0</strong> — 驱动初始化需要最小内存</li><li><strong>u-boot 的 bootsys 不展开环境变量</strong> — <code>${othbootargs}</code> 是死字符串</li><li><strong>TFTP 在 u-boot 下可能不稳定</strong> — 用 recovery + dd 更可靠</li><li><strong>init 会自动重启服务</strong> — 必须用 <code>stop</code> 命令，不能只 <code>kill</code></li></ol>',22)])])}const m=i(o,[["render",r]]);export{_ as __pageData,m as default};
